@id("a0bddbd3-e6c6-41ee-8f5b-c46f66070688")
@nodeType("6")

-- Every ratio here is a ratio of totals, divided once at vendor grain. The additive
-- sums are carried through so downstream consumers can re-aggregate correctly.
SELECT
     CAST("ROLLUP"."VENDOR_ID" AS NUMBER(38,0)) AS "VENDOR_ID" @id("8aa326e1-a3c9-4275-8f1d-eb46ec9672c9"),
     CAST("ROLLUP"."TRIP_COUNT" AS NUMBER(38,0)) AS "TRIP_COUNT" @id("5d2c0935-4e0d-46d3-bcee-271fb70c33a6"),
     CAST("ROLLUP"."TRIP_COUNT_BILLABLE" AS NUMBER(38,0)) AS "TRIP_COUNT_BILLABLE" @id("ffea89e0-6fbc-4566-b9eb-1890d1dcc816"),
     CAST("ROLLUP"."TRIP_COUNT_VOID" AS NUMBER(38,0)) AS "TRIP_COUNT_VOID" @id("f1e20d91-6d91-4e30-bea8-b0c88b051f7c"),
     CAST("ROLLUP"."TRIP_COUNT_L12M" AS NUMBER(38,0)) AS "TRIP_COUNT_L12M" @id("6e66c289-8356-4bf0-9eeb-78d06b3b554a"),
     CAST("ROLLUP"."ACTIVE_MONTHS" AS NUMBER(38,0)) AS "ACTIVE_MONTHS" @id("0b4d8529-79c0-4da4-b885-41a9bb4eb428"),
     CAST("ROLLUP"."FIRST_TRIP_DATETIME" AS TIMESTAMP) AS "FIRST_TRIP_DATETIME" @id("2808cb1d-8059-45e7-96c0-7c8ef174030a"),
     CAST("ROLLUP"."LAST_TRIP_DATETIME" AS TIMESTAMP) AS "LAST_TRIP_DATETIME" @id("64bb0c58-95ee-4deb-952f-c7dff036ccf6"),

     CAST("ROLLUP"."TRIP_DISTANCE_TOTAL" AS NUMBER(38,4)) AS "TRIP_DISTANCE_TOTAL" @id("6b2c16fe-12be-4f29-a911-6f366f95929e"),
     CAST("ROLLUP"."TRIP_DISTANCE_TOTAL_BILLABLE" AS NUMBER(38,4)) AS "TRIP_DISTANCE_TOTAL_BILLABLE" @id("9e07a350-5dba-41c2-a23d-5bd0b1c1d054"),
     CAST("ROLLUP"."TRIP_DURATION_MINUTES_TOTAL" AS NUMBER(38,4)) AS "TRIP_DURATION_MINUTES_TOTAL" @id("9051d6b2-5d1b-403c-ab56-b97f2cf1c280"),
     CAST("ROLLUP"."FARE_AMOUNT_TOTAL" AS NUMBER(38,2)) AS "FARE_AMOUNT_TOTAL" @id("fded256a-c851-41bc-ac7a-7197010b6b4e"),
     CAST("ROLLUP"."FARE_AMOUNT_TOTAL_BILLABLE" AS NUMBER(38,2)) AS "FARE_AMOUNT_TOTAL_BILLABLE" @id("1c07c9bb-6329-42d8-a67f-76d6ebf67122"),
     CAST("ROLLUP"."TOTAL_AMOUNT_TOTAL" AS NUMBER(38,2)) AS "TOTAL_AMOUNT_TOTAL" @id("47cfc98f-c5d8-4e04-845b-ae13445e1358"),
     CAST("ROLLUP"."TIP_AMOUNT_TOTAL" AS NUMBER(38,2)) AS "TIP_AMOUNT_TOTAL" @id("6948bd6a-d914-414b-bbfd-3263f97967b7"),
     CAST("ROLLUP"."TOLLS_AMOUNT_TOTAL" AS NUMBER(38,2)) AS "TOLLS_AMOUNT_TOTAL" @id("4a16239b-e0fd-4e73-91f5-8be6c5091dee"),

     CAST("ROLLUP"."FARE_AMOUNT_TOTAL_BILLABLE" / NULLIF("ROLLUP"."TRIP_DISTANCE_TOTAL_BILLABLE", 0) AS NUMBER(12,4)) AS "FARE_REVENUE_PER_MILE" @id("ccf37193-2a54-4931-ba14-b0487e0434a9") @description("SUM(fare_revenue) / SUM(trip_distance) per the Fare Revenue per Mile metric definition. Base fare only, void trips excluded. Valid at vendor grain only"),
     CAST("ROLLUP"."FARE_AMOUNT_TOTAL_BILLABLE" / NULLIF("ROLLUP"."TRIP_COUNT_BILLABLE", 0) AS NUMBER(12,4)) AS "FARE_REVENUE_PER_TRIP" @id("2beabb62-256e-4e3b-977c-e471c3859a61"),
     CAST("ROLLUP"."TRIP_DISTANCE_TOTAL" / NULLIF("ROLLUP"."TRIP_COUNT", 0) AS NUMBER(12,4)) AS "TRIP_DISTANCE_AVG" @id("98417f3c-0d9e-4bf6-8ef2-cc44b46d8adf") @description("Recomputed from totals at vendor grain, not an average of monthly averages"),
     CAST("ROLLUP"."TRIP_DURATION_MINUTES_TOTAL" / NULLIF("ROLLUP"."TRIP_COUNT", 0) AS NUMBER(12,4)) AS "TRIP_DURATION_MINUTES_AVG" @id("17dfa220-3275-437c-af4d-37a81b634b0a"),
     CAST("ROLLUP"."TRIP_DISTANCE_TOTAL" / NULLIF("ROLLUP"."TRIP_DURATION_MINUTES_TOTAL" / 60, 0) AS NUMBER(12,4)) AS "TRIP_SPEED_MPH_AVG" @id("365bae4e-1de1-4bdc-9ebf-bc2bff28298a"),
     CAST("ROLLUP"."PASSENGER_COUNT_TOTAL" / NULLIF("ROLLUP"."TRIP_COUNT", 0) AS NUMBER(12,4)) AS "PASSENGERS_PER_TRIP_AVG" @id("90268401-06ee-4cef-9192-d94587ccc87d"),

     CAST("ROLLUP"."TOTAL_AMOUNT_CC" / NULLIF("ROLLUP"."TOTAL_AMOUNT_TOTAL", 0) AS NUMBER(12,4)) AS "REVENUE_SHARE_CC" @id("0b646b24-f048-4ed5-9f6e-1a6f354876d2"),
     CAST("ROLLUP"."TOTAL_AMOUNT_CASH" / NULLIF("ROLLUP"."TOTAL_AMOUNT_TOTAL", 0) AS NUMBER(12,4)) AS "REVENUE_SHARE_CASH" @id("664b1909-f0d5-4181-a5e4-842b6baead44"),
     CAST("ROLLUP"."TOTAL_AMOUNT_VOID" / NULLIF("ROLLUP"."TOTAL_AMOUNT_TOTAL", 0) AS NUMBER(12,4)) AS "REVENUE_SHARE_VOID" @id("b32676ea-137b-489a-bb08-008a6c46d2e4"),
     CAST("ROLLUP"."TRIP_COUNT_VOID" / NULLIF("ROLLUP"."TRIP_COUNT", 0) AS NUMBER(12,4)) AS "VOID_TRIP_RATE" @id("3bedd4bc-8ed0-493e-9a54-f5a2d968fdd6"),
     CAST("ROLLUP"."TIP_AMOUNT_TOTAL" / NULLIF("ROLLUP"."FARE_AMOUNT_TOTAL_BILLABLE", 0) AS NUMBER(12,4)) AS "TIP_RATE" @id("65744d24-964c-483d-8f2a-4e22f6d4ed76"),

     CAST("ROLLUP"."FARE_AMOUNT_L12M" / NULLIF("ROLLUP"."TRIP_DISTANCE_L12M", 0) AS NUMBER(12,4)) AS "FARE_REVENUE_PER_MILE_L12M" @id("953149ad-095d-4e40-b7dc-dd13309bf5ba"),
     CAST("ROLLUP"."FARE_AMOUNT_PRIOR_12M" / NULLIF("ROLLUP"."TRIP_DISTANCE_PRIOR_12M", 0) AS NUMBER(12,4)) AS "FARE_REVENUE_PER_MILE_PRIOR_12M" @id("2d2459bd-e040-4bbe-838b-a7ba569252b4"),
     CAST(
          ("ROLLUP"."FARE_AMOUNT_L12M" / NULLIF("ROLLUP"."TRIP_DISTANCE_L12M", 0))
          / NULLIF("ROLLUP"."FARE_AMOUNT_PRIOR_12M" / NULLIF("ROLLUP"."TRIP_DISTANCE_PRIOR_12M", 0), 0) - 1
     AS NUMBER(12,4)) AS "FARE_REVENUE_PER_MILE_YOY_CHANGE" @id("75d188ae-ff6f-4917-8c39-c89a8888399e") @description("Trailing 12 months versus the preceding 12, anchored on the latest trip in the data")
FROM {{ ref('SILVER', 'SQL_VENDOR_TRIP_ROLLUP') }} "ROLLUP"
